let state;try{state=JSON.parse(localStorage.getItem('between-lines-episodes-v2'))||{saved:[],runs:{}}}catch{state={saved:[],runs:{}}}let view='all',filter='Все',query='',active=0;const $=s=>document.querySelector(s);const imageUrl=(s,w=1000)=>['assets/city.png','assets/summer.png','assets/moon.png'][s.id];function save(){try{localStorage.setItem('between-lines-episodes-v2',JSON.stringify(state))}catch{}$('#mycount').textContent=Object.keys(state.runs).length}function render(){const list=stories.filter(s=>(view==='all'||(view==='saved'?state.saved.includes(s.id):state.runs[s.id]))&&(filter==='Все'||s.tags.includes(filter))&&s.title.toLowerCase().includes(query));$('#cards').innerHTML=list.map(s=>`<article class="card" style="padding:0"><div class="cover"><img src="${imageUrl(s)}" alt="${s.title}" loading="lazy"><button class="card-open" data-play="${s.id}" aria-label="Читать ${s.title}"><span class="cover-title">${s.title}</span></button><span class="cover-label">${s.label}</span><button class="bookmark ${state.saved.includes(s.id)?'saved':''}" data-save="${s.id}" aria-label="${state.saved.includes(s.id)?'Удалить из избранного':'В избранное'}" aria-pressed="${state.saved.includes(s.id)}">${state.saved.includes(s.id)?'♥':'♡'}</button></div><div class="card-tags">${s.tags.join(' · ').toUpperCase()}</div><h3>${s.title}</h3><p>${s.description}</p><div class="card-meta"><span>1 эпизод &nbsp;·&nbsp; ≈ 10 минут</span><button data-play="${s.id}">${state.runs[s.id]?.step>=s.scenes.length?'Перечитать':state.runs[s.id]?'Продолжить':'Читать'} </button></div></article>`).join('')||'<p class="empty">Здесь пока тихо.<br>Выбери историю в библиотеке или попробуй другой поиск.</p>';$('#section-title').innerHTML=`${view==='mine'?'Мои истории':view==='saved'?'Избранное':'Коллекция историй'}<span>${String(list.length).padStart(2,'0')}</span>`;save()}
function play(id){active=id;if(!state.runs[id])state.runs[id]={step:0,trust:0,truth:0,boundary:0};save();showScene();if(!$('#reader').open)$('#reader').showModal();document.body.style.overflow='hidden';requestAnimationFrame(()=>{$('#reader').scrollTop=state.runs[id].scroll||0})}function showScene(){renderReadingScene()}function closeReader(){$('#reader').close();document.body.style.overflow='';render()}document.addEventListener('click',e=>{const p=e.target.closest('[data-play]');if(p)play(Number(p.dataset.play));const b=e.target.closest('[data-save]');if(b){const id=Number(b.dataset.save);state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];render()}const c=e.target.closest('[data-choice]');if(c){const r=state.runs[active],choice=stories[active].scenes[r.step][2][Number(c.dataset.choice)];r[choice[1]]++;r.step++;r.beat=0;r.scroll=0;save();showScene()}if(e.target.closest('[data-replay]'))restart();if(e.target.closest('[data-library]'))closeReader()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===b));render();$('#library').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('.chip').forEach(n=>n.classList.toggle('selected',n===b));render()});$('.search input').oninput=e=>{query=e.target.value.toLowerCase().trim();render()};function restart(){state.runs[active]={step:0,trust:0,truth:0,boundary:0};save();showScene()}$('#restart').onclick=restart;$('#exit').onclick=closeReader;$('#reader').addEventListener('close',()=>{document.body.style.overflow='';render()});function info(html){$('#info-content').innerHTML=html;$('#info').showModal()}$('#profile').onclick=()=>info(`<div class="eyebrow">ТВОЯ ЧИТАТЕЛЬСКАЯ КОМНАТА</div><h2>Истории остаются.</h2><p>Начато историй: ${Object.keys(state.runs).length}<br>Прочитано: ${Object.entries(state.runs).filter(([id,r])=>r.step>=stories[id].scenes.length).length}<br>В избранном: ${state.saved.length}</p><p>Твой прогресс хранится в этом браузере. Возвращайся, когда захочется ещё одной истории.</p>`);$('#about').onclick=()=>info('<div class="eyebrow">МЕЖДУ СТРОК</div><h2>Твоя версия важна.</h2><p>Первые серии трёх оригинальных интерактивных историй о близости, честности и личных границах. Все персонажи — взрослые.</p><p>Выборы формируют характер героини и отношения. Здесь нет платных ответов и таймера ожидания.</p>');$('#info .close').onclick=()=>$('#info').close();render();

let scrollSaveTimer;$('#reader').addEventListener('scroll',()=>{clearTimeout(scrollSaveTimer);scrollSaveTimer=setTimeout(()=>{if($('#reader').open&&state.runs[active]){state.runs[active].scroll=$('#reader').scrollTop;save()}},200)});
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}

